with d as (select value r from jsonb_array_elements($q$[{"notes":["Sorrel is best in spring and early summer. Grow it in a pot if you can, it comes back year after year.","The soup is best eaten the day it's made. Don't add the egg until just before serving, it doesn't keep well.","If you can't find sorrel, use spinach with a squeeze of lemon juice, though the flavour will be milder and less tart.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Heat the oil in a large pot over medium heat. Add the diced onion and cook, stirring occasionally, until soft and pale golden, about 5 minutes."},{"text":"Add the potato and stock, and bring to a simmer. Cook, uncovered, for about 12 minutes, until the potato is tender."},{"text":"Add the sorrel and stir through. Cook for 2–3 minutes, just until the sorrel wilts and softens."},{"text":"In a small bowl, whisk the eggs together. Remove the pot from the heat and slowly pour the eggs into the hot (but no longer boiling) soup while stirring gently with a fork, this will create soft ribbons of cooked egg."},{"text":"Taste and season with salt and pepper. Stir through most of the fresh dill."},{"text":"Ladle into bowls and top with a spoonful of Greek yoghurt if you like, and a final sprinkle of fresh dill."}],"id":"660144d5-cc7e-457d-ae47-2983b629f455"},{"notes":["Ndolé has a pleasantly bitter taste, if you can't find it at an African grocer, spinach works but tastes gentler","Make this up to the point of adding the fish, cool quickly, and refrigerate for up to two days. Reheat gently and add fresh fish just before serving","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"00defa04-aac0-4962-ba77-530fd0edee1c"},{"notes":["You can prepare the onion, garlic and ginger up to 2 hours ahead. Store in small bowls, covered.","Frozen prawns work well; thaw them completely and pat dry before cooking so they don't release water into the curry.","Food safety: Cook prawns and other crustaceans until the shells turn pink and the flesh is opaque and firm."],"steps":[{"text":"Heat the mustard oil in a heavy-bottomed pan over medium-high heat. Once it's hot and fragrant, add the sliced onion and cook, stirring often, until golden and just beginning to crisp at the edges, about 6 minutes."},{"text":"Add the minced garlic and grated ginger to the pan and stir constantly for about 1 minute until fragrant. Be careful not to let it burn."},{"text":"Add the slit green chillies to the pan and cook for another minute, then add the ground turmeric and cumin. Stir well to coat the onions and release the spice aromas, about 30 seconds, until fragrant."},{"text":"Pour in the coconut cream and stir to combine. Bring the mixture to a gentle simmer and let it bubble softly for 3 to 4 minutes, allowing the flavours to meld."},{"text":"Slide the prawns into the simmering coconut curry and stir gently. Cook for 4 to 5 minutes, stirring occasionally, until the prawns turn pink and opaque throughout. Do not overcook or they will toughen."},{"text":"Taste and adjust the salt to your liking. If you prefer a thinner sauce, add a splash of warm water. Serve hot with steamed rice, garnished with fresh coriander if you like."}],"id":"2f1e3195-ff50-423b-a174-fa5598dc72e3"},{"notes":["Make it ahead: prepare in the morning, cover and refrigerate, then roast in the evening, just add 30 minutes to the cooking time.","Kai Māori: serve with boiled corn, pumpkin, or kūmara if you want it more like a proper boil-up.","Leftovers shred and freeze well for kai later in the week.","Food safety: Slow-cooked meat is safe once it is tender and the centre has reached at least 75°C."],"steps":[{"text":"Heat oven to 160°C. Pat the lamb shoulder dry and season well all over with salt and pepper."},{"text":"Heat oil in a large roasting pan over medium-high heat. Sear the lamb on all sides until golden brown, about 10 minutes total. Remove and set aside."},{"text":"In the same pan, toss the potatoes, carrots, pumpkin, onions and garlic together. Season with salt and pepper."},{"text":"Place the lamb back on top of the vegetables. Scatter rosemary over everything and pour water around the base."},{"text":"Cover the pan tightly with foil, then place a roasting pan lid or another baking tray on top to seal it well, this traps the steam like an earth oven would. Press the foil around the rim until the seal is tight and no steam escapes."},{"text":"Roast low and slow for 5 hours, until the lamb is fall-apart tender and the vegetables are soft and caramelised."},{"text":"Carefully remove the foil (watch the steam), then pull the meat from the bone. It is ready when it is tender and falls away easily. Serve everything together with the cooking liquid spooned over."}],"id":"0172ffa8-39b6-4fb9-aa05-1b679372ee09"},{"notes":["Samgyetang is traditionally eaten on Chobok, the hottest days of summer, to restore energy. Dong-hyun says it keeps for two days in the fridge, reheat gently before serving.","If you can find Korean red ginseng (홍삼), substitute 3 or 4 pieces for the fresh ginseng; they are denser and more assertive.","Use a chicken under 1 kg (a young bird); older birds take too long and become stringy.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Bring the water to a boil in a large pot until it is at a steady rolling boil. Add the salt."},{"text":"Meanwhile, combine the glutinous rice, date halves, crushed garlic, and salt in a small bowl. Stuff the chicken cavity loosely with this mixture, do not pack it tight, as the rice will expand. Secure the opening with a cocktail pick if needed."},{"text":"Gently lower the whole chicken into the boiling salted water. Return to a boil, then reduce the heat to a bare simmer, with only a few small bubbles breaking the surface. Skim the surface once, at the beginning, until the scum is cleared."},{"text":"Add the ginseng, whole red dates, garlic cloves, ginger, and mushrooms to the broth around the chicken. Cover the pot and simmer gently for 1 hour and 45 minutes, until the chicken is very tender and cooked through (the thigh should reach 75°C inside). Do not stir, and add no more salt, the flavour is in the restraint."},{"text":"Add the spring onion whites in the last 5 minutes."},{"text":"Remove the chicken carefully with tongs and transfer to a serving bowl or to individual bowls. Ladle the hot broth over it. Serve the ginseng, dates, garlic, mushrooms, and ginger alongside in the bowl, for each person to enjoy."}],"id":"3ae6eb82-e8fb-474c-92d8-bdf5c418f730"},{"steps":[{"text":"Make the dipping sauce: whisk together soy sauce, rice vinegar, sesame oil, gochugaru if using, and garlic. Set aside."},{"text":"Make the batter: whisk flour, salt, water and egg together until smooth. Fold in the grated zucchini, carrot and spring onion, don't overmix."},{"text":"Heat 2 tbsp oil in a large frying pan over medium-high heat until it shimmers."},{"text":"Working in batches, pour the batter into the pan in rough 10 cm pancakes (they don't need to be perfect). Fry for 3 to 4 minutes until the edges are golden and crispy."},{"text":"Flip and fry for a further 2 minutes until golden on the second side and cooked through."},{"text":"Drain on paper towel and serve hot with dipping sauce."}],"id":"1d376942-f6c6-402b-a7c9-b23d179660a3"},{"notes":["Make the braise up to 2 days ahead and refrigerate; it actually tastes better the next day. Assemble the gratin and bake just before serving.","The reserved braising liquid is good in soups or risotto.","Any leftover gratin can be reheated gently in a 160°C oven, covered, until warm through.","Food safety: Slow-cooked meat is safe once it is tender and the centre has reached at least 75°C."],"steps":[{"text":"Heat the oil in a heavy-bottomed pot or casserole over medium-high heat. Season the oxtail pieces with salt and pepper, then brown them in batches, about 3 minutes per side. Don't crowd the pot. Set the meat aside."},{"text":"In the same pot, sauté the onions, carrots and celery until lightly golden, about 8 minutes. Add the garlic, stir, then add the tomato paste and cook for 2 minutes, stirring constantly."},{"text":"Pour in the red wine, scraping up any brown bits from the bottom of the pot. Add the beef stock, bay leaves and thyme. Return the oxtail to the pot and bring to a simmer. Cover and braise in a 160°C oven for 3 hours, until the meat is very tender and falls easily from the bone."},{"text":"Remove the pot from the oven and let cool slightly. Strain the braising liquid through a fine sieve, pressing gently on the vegetables to extract all the liquid. Pick the meat from the bones, discarding the bone and any fat. You should have about 400–500 g of shredded meat and about 600 ml of braising liquid."},{"text":"Make the béchamel: melt the butter in a saucepan over medium heat. Whisk in the flour and cook for 2 minutes, stirring constantly, don't let it brown. Gradually whisk in the warm milk, whisking constantly to avoid lumps. Cook, stirring often, until the sauce is thick and smooth, about 8 minutes. Season with salt, white pepper and nutmeg."},{"text":"Combine the shredded oxtail meat with 300 ml of the braising liquid (reserve the rest for another use). Gently fold in the béchamel sauce until just combined."},{"text":"Transfer the mixture to a gratin dish. Scatter the Gruyère evenly over the top. Bake at 200°C until the gratin is bubbling around the edges and the cheese is golden brown, about 30–40 minutes. Let rest for 5 minutes before serving."}],"id":"4d39f4e8-95e1-4c91-a089-66d38bb77917"},{"notes":["Bitso-bitso means 'this and that' in Kapampangan, here, a mix of offal. You can add pork kidney (about 150 g, trimmed and halved) if you like.","The adobo keeps well in the fridge for up to 3 days. The flavour deepens overnight.","Fresh offal is essential. Ask your butcher for the freshest pork liver and heart available."],"id":"f239a922-be5d-4158-997e-f7e4b073b358"},{"notes":["Make it a day ahead: cool, cover, and refrigerate. Reheat gently on the stove, adding a splash of water if it's too thick.","Use bone-in lamb shoulder if you can find it, the bones add flavour.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"e167b121-3807-458b-9814-24c5bcac2971"},{"notes":["You can prep the parcels a few hours ahead, cover them with a damp cloth, and steam them just before serving.","If you can't find banana leaves, use parchment paper, it won't look as pretty but tastes the same."],"id":"308561f3-7397-4eec-8107-9c0b8b3b08bc"},{"notes":["Make sure your rice is cooled first, this stops it from becoming mushy. Leftover rice from yesterday works perfectly.","If you don't have tinned tomatoes, use 150 g of fresh tomato, chopped, or 2 tbsp tomato paste mixed with 2 tbsp water.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system. Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"id":"1006703c-41be-4fae-960f-0d9d3871165f"},{"notes":["You can cook the pork up to a day ahead and refrigerate it, this actually makes slicing cleaner. Reheat gently in the wok before adding the bean paste.","The doubanjiang (or doubanjiang with chilli if you prefer a little more warmth) is your backbone here; don't skip it or use substitutes. It's what makes this dish sing.","Serve with plain steamed rice to balance the rich, umami sauce.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"steps":[{"text":"Cut the pork belly into thin slices, about 3 mm thick (easier if the pork is slightly cold). Simmer the pork in a pot of water for 20 minutes until just cooked through, then drain and set aside on a plate."},{"text":"Heat 1 tbsp neutral oil in a wok or large frying pan over medium heat. Add the spring onion whites, garlic and ginger, stirring for about 1 minute until fragrant."},{"text":"Add the doubanjiang and stir constantly for 2 minutes, breaking it up as it heats, until the paste darkens slightly and releases its aroma."},{"text":"Add the cooked pork slices and toss gently but thoroughly, coating each piece in the bean paste, for about 3 minutes."},{"text":"Add the capsicums, soy sauce, sugar and a pinch of salt. Cook, stirring often, for 8 to 10 minutes until the peppers are tender and the sauce is glossy and clingy."},{"text":"Add the spring onion greens, drizzle with sesame oil, toss once and taste, adjust salt if needed. Serve hot with steamed rice."}],"id":"d2686fc2-58e3-45ba-947f-a84f5f1679dc"},{"notes":["Make sure you don't lift the lid while the rice is cooking, opening it lets the steam out and stops the rice cooking evenly.","This keeps in the fridge for up to three days. Reheat gently in a rice cooker or microwave with a splash of water."],"id":"a2e522d8-cc1f-4161-8545-3fd1a29b2eec"},{"notes":["You can stir in sautéed mushrooms or crispy bacon to the eggs before baking if you like.","The æggeost is best served warm, but it's also nice cold for lunch the next day.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"a3f9afea-38be-44e4-b49f-21eb0f0610f7"},{"notes":["Kibbeh can be shaped up to 4 hours ahead and refrigerated, but don't freeze before frying, the texture gets grainy.","If the mixture is too sticky to work with, add a little more bulgur; if it's too dry, add cold water a teaspoon at a time.","The filling must be completely cool before you stuff, or it will start cooking the shell from inside.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Make the filling first: heat the olive oil in a large pan over medium-high heat. Add the chopped onion and cook until soft and golden, about 4 minutes. Add the mince, breaking it up as it cooks, and stir for 5–6 minutes until cooked through. Add the pine nuts, cinnamon and cloves, season with salt and pepper, and stir for another minute. Set aside to cool completely."},{"text":"Meanwhile, rinse the bulgur under cold water until the water runs clear, then drain well. In a bowl, combine the bulgur, 500 g mince, chopped onion, allspice and cinnamon. Season with salt and pepper. Add cold water a little at a time, mixing with your hands, until the mixture holds together like a dough, you want it moist but not wet. Cover and rest for 10 minutes."},{"text":"Wet your hands with cold water. Take a handful of the bulgur mixture (about the size of a golf ball) and shape it into an oval. Push your thumb into the centre to make a cavity, then gently hollow it out, rotating it in your palm, until the walls are thin. Fill with about 1 tbsp of the cooled filling, then pinch and seal the opening, gently smoothing the seam. Shape into an oval or pointed torpedo. Repeat with the remaining mixture."},{"text":"Heat the oil to 160°C in a deep heavy-based pot or wok (use a thermometer to check). Fry the kibbeh in batches, without crowding the pan, for 4–5 minutes, turning halfway, until golden brown and crispy all over. Do not let the oil get too hot or they'll brown before cooking through. Remove with a slotted spoon and drain on paper towel."},{"text":"Serve the kibbeh warm with Greek yoghurt and lemon wedges on the side."}],"id":"b6db635e-dffa-49e3-8ae9-81ce14595183"},{"notes":["The marinade can be prepared up to 24 hours ahead; overnight is ideal for full flavour.","The peanut sauce can be made earlier in the day and reheated gently before serving.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"id":"e29e4104-6ce5-464c-8d30-549a3c41607c"},{"notes":["Bamia freezes beautifully. Cool completely, then freeze for up to 3 months. Reheat gently on the stove with a splash of water.","This is even better the next day as the flavours deepen. Make it ahead and warm through before serving.","Some Iraqi cooks add a touch of pomegranate molasses at the end instead of lemon juice, try it both ways and see what you prefer.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"84928a00-625b-4d68-8286-50aea36cda94"},{"notes":["Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"903e9478-bd1c-4e1e-bba8-118b5543c4c0"},{"notes":["Freeze in ice-cube trays for perfect portion control. One or two cubes is usually enough for a child's serve, three to four for an adult.","Make a double or triple batch and freeze for up to three months. No thawing needed, drop cubes straight into pasta water or a hot pan.","Swap the gravy powder for 1 tsp dried oregano and a splash of Worcestershire sauce if you prefer.","Cook mince and sausages until they reach 75°C in the centre, with no pink left.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"steps":[{"text":"Heat the oil in a large frying pan over medium-high heat. Add the onion and cook, stirring, until soft, about 3 minutes."},{"text":"Add the garlic and cook for 30 seconds until fragrant."},{"text":"Add the beef mince and break it up as it cooks, stirring often, until browned through, about 5 minutes."},{"text":"Stir in the carrot and tomato paste, cooking for 1 minute."},{"text":"Add the crushed tomatoes and gravy powder, stir well to combine, and bring to a simmer, cooking until the sauce has thickened and turned glossy."},{"text":"Cook, stirring occasionally, for 8 to 10 minutes until the sauce thickens slightly and the carrot is tender. Season with salt and pepper to taste."},{"text":"Cool completely, then freeze in ice-cube trays. Once frozen, pop the cubes into a freezer bag and label with the date. Thaw and reheat on the stove or stir straight into hot pasta water."}],"id":"f7ae6ba3-607e-4461-bad0-6fc1022e6939"},{"diets":[],"notes":["This is a dish about technique, not ingredients. The emulsion of cheese and starch from the pasta water is everything. If your sauce breaks, start again with a little cold water.","Use whole peppercorns and crack them yourself just before cooking, pre-ground pepper will be too fine.","For a vegetarian version, use a vegetarian hard cheese (made without animal rennet)."],"steps":[{"text":"Bring a large pot of salted water to a rolling boil, until large bubbles break across the whole surface. The water should taste like the sea."},{"text":"Toast the cracked pepper in a large, dry frying pan over medium heat for 1 minute, stirring, until fragrant. Add 100 ml of pasta water and bring to a gentle simmer."},{"text":"Cook the spaghetti until al dente, about 9–10 minutes. Reserve 200 ml of pasta water before draining."},{"text":"Add the drained spaghetti to the pan with the pepper water. Remove from heat. Working quickly, add half the grated cheese, tossing constantly with two wooden spoons. Add pasta water a splash at a time, tossing all the while, until the sauce comes together and clings to the pasta. It should be creamy but have no cream in it."},{"text":"Divide between two bowls. Finish with the remaining cheese and a crack of fresh pepper."}],"id":"f20a154b-03c2-4f13-8178-1eeae5b31202"},{"notes":["Zaalouk keeps well in the fridge for up to 3 days; serve warm or at room temperature.","You can roast the eggplants directly over a gas flame for a more charred, smoky flavour if you prefer, use tongs and turn carefully.","This is traditionally served as part of a mezze spread alongside olives, preserved lemons and bread."],"steps":[{"text":"Preheat your oven to 200°C. Prick each eggplant several times with a fork, then place on a baking tray. Roast for 35–40 minutes, turning halfway, until the skin is blackened and the flesh is very soft."},{"text":"While the eggplants roast, warm 2 tbsp olive oil in a large pan over medium heat. Add the chopped garlic and cook gently for 1 minute until fragrant, don't let it brown."},{"text":"Add the chopped tomatoes to the pan, season with salt and pepper, and simmer for 8–10 minutes, stirring occasionally, until the tomatoes begin to break down and release their juices."},{"text":"When the eggplants are soft and charred, remove them from the oven and let cool for a few minutes. Peel away the skin and chop the flesh into small pieces, don't worry about getting it perfect; some texture is good."},{"text":"Add the eggplant to the tomato pan and stir gently to combine. Cook for 2 minutes to warm through, then taste and adjust the seasoning."},{"text":"Stir in most of the fresh coriander, reserving some to scatter over the top. Transfer to a serving dish and drizzle with a little extra olive oil. Scatter the remaining coriander over the top and serve warm or at room temperature with bread."}],"id":"0690e255-ed48-46c2-bd1f-dd42a531caaa"},{"notes":["Store in an airtight container for up to 5 days. They stay crispy at room temperature.","Don't skip the honey, it's traditional and brings everything together. Just a light coating is enough.","If you want to make these ahead, you can prepare the dough and filling the day before and assemble and fry them on the day."],"steps":[{"text":"Make the filling first: melt the 60 g butter in a saucepan over low heat. Add the dates and stir constantly, breaking them down with the back of a wooden spoon, until they form a smooth paste, about 5 minutes. Stir in the orange blossom water and salt, then set aside to cool."},{"text":"For the dough: put the semolina, baking powder and salt in a bowl. Add the softened butter pieces and rub together with your fingertips until the mixture looks like breadcrumbs. Add the orange blossom water and warm water, a little at a time, mixing gently until the dough comes together, it should feel soft and slightly moist but not sticky. Knead lightly for 1 minute."},{"text":"Lightly oil your work surface. Take a piece of dough about the size of a walnut and flatten it into a disc about 5 mm thick. Place a teaspoon of date paste in the centre, fold the dough in half over the filling, then pinch the edges firmly to seal. You can press it gently with the tines of a fork to make ridges if you like. Repeat with the remaining dough and filling, you should make about 12 cookies."},{"text":"Heat the neutral oil in a deep saucepan to 180°C (a piece of dough should sizzle immediately and turn golden in about 30 seconds). Working in batches so you don't crowd the pan, fry the makroudh until they're deep golden brown all over, about 2–3 minutes, turning halfway through. Use a slotted spoon to transfer them to a paper-towel-lined plate."},{"text":"While they're still warm, brush or drizzle the warmed honey lightly over each makroudh. Let them cool for a few minutes on the paper towels, they'll crisp up as they cool."}],"id":"0444a0e1-2aff-4d3d-8129-0cf9591b2ae6"},{"notes":["Chimichurri can be made up to 2 hours ahead and kept at room temperature.","Asado de tira is best cooked over charcoal or hardwood fire. If using a gas grill, preheat to high heat and cook for the same time, checking for tenderness.","Internal temperature for medium is 65°C. For a softer, more melting texture, cook to 68°C.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"id":"2fb2fee3-f380-4bee-afb7-f386d0615d4b"},{"notes":["Make it ahead: this keeps in the fridge for up to 5 days, or freeze it for a month.","No blender? Mash it with a fork or stick blender in the pan.","If you can't get red chillies, use jalapeños, or even a pinch of chilli powder, it's still salsa."],"steps":[{"text":"Heat a large frying pan or comal (or frying pan if that's what you have) over medium-high heat. Work in batches if needed: char the tomatoes, turning occasionally, until soft and blackened in spots, about 5 minutes. Set aside."},{"text":"In the same pan, char the red chillies and garlic cloves until soft and blistered, about 3 minutes. Add to the tomatoes."},{"text":"Add the onion to the pan and cook until soft and lightly coloured, about 3 minutes."},{"text":"Transfer the tomatoes, chillies, garlic and onion to a blender. Blend until smooth or to your preferred texture, some people like it chunky."},{"text":"Return the salsa to the pan and simmer over medium heat for 5 minutes, stirring occasionally, until it's thick and the flavours have come together."},{"text":"Season with salt to taste. Serve warm or at room temperature with tacos, quesadillas or whatever you're cooking."}],"id":"e3b9f33a-b2bb-4e70-af7b-c9565ac8784e"},{"notes":["Make this a day ahead, the flavours deepen overnight and the beef becomes even more tender. Reheat gently on the stove with a splash of water if the sauce is too thick.","If you prefer a hotter rendang, add extra red chillies to the paste, or finely chop a bird's eye chilli to stir in at the end.","Serve with steamed jasmine rice and a cool cucumber sambal to cut through the richness.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"b9bab978-a0d4-4dd6-b37e-33de869e133e"},{"notes":["Prep everything before you start cooking, there's no time once the wok is hot.","If you can't find king prawns, use medium prawns (just reduce the cooking time by 30 seconds).","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"36e4e1f8-543e-4772-bf19-3e8d035a4463"},{"notes":["This curry tastes even better the next day. Cool and store in the fridge for up to 3 days, or freeze for up to a month.","Dilan brings this to work in a thermos flask for night shifts, it keeps beautifully and reheats gently."],"steps":[{"text":"Heat oil in a large pot over medium heat. Add onion and cook, stirring, until soft and golden, about 5 minutes."},{"text":"Add garlic and ginger, stir well, and cook for 1 minute until fragrant."},{"text":"Add curry powder and turmeric, stir to coat the onions, and cook for 30 seconds, until fragrant."},{"text":"Add eggplant cubes and stir to coat in the spice mixture. Cook for 2 minutes."},{"text":"Pour in coconut milk and water. Add the green chillies and season with salt."},{"text":"Bring to a simmer, then reduce heat to low. Cover and cook for 15 to 18 minutes, until the eggplant is tender and the curry has thickened slightly."},{"text":"Taste and adjust salt if needed. Serve hot with rice."}],"id":"38cacbd4-dc01-448b-b445-c62986ac2929"},{"notes":["Keeps in the fridge for 3 days, or freeze for up to 3 months. Reheat gently on the stove.","If you can't find dried bush tomato at your local grocer, look for it at farmers markets or Aboriginal-owned food suppliers.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"2a8b9a64-72ec-4863-b160-34746f53bab3"},{"notes":["Serves well alongside shrimp, sausage or collard greens.","Can be made a day ahead and reheated gently on the stove with a splash of stock."],"steps":[{"text":"Heat a cast iron frying pan over medium heat. Cook the bacon until crispy, about 5 minutes, then transfer to a plate, leaving the fat in the pan."},{"text":"Add the onion to the bacon fat and cook, stirring often, until soft and starting to caramelize, about 8 minutes."},{"text":"Stir in the rice and cook for 1 minute, coating it in the fat."},{"text":"Add the crushed tomatoes, stock, salt, pepper and cayenne (if using). Stir well, then bring to a gentle simmer until small bubbles break the surface."},{"text":"Cover and cook for 20 minutes without lifting the lid, until the rice is tender and has absorbed the liquid."},{"text":"Remove from heat, stir in the cooked bacon, and let it rest for 2 minutes before serving."}],"id":"7d12311e-f60d-4489-814a-0dbfa2cf3231"},{"notes":["The broth can be made up to 3 days ahead and stored in the fridge, or frozen for up to 3 months. Matzo balls can be cooked and frozen separately for up to 1 month.","For a lighter broth, use chicken breasts instead of bones; reduce cooking time to 45 minutes. For richer broth, add extra chicken fat (schmaltz) when serving.","The soda water is key to light, fluffy matzo balls, don't skip it. And cold hands matter more than you'd think; it keeps the batter from getting tough.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Make the broth: place chicken bones in a large pot, cover with 3 litres of cold water, and bring to a boil. Skim off any grey foam that rises to the surface, about 2 minutes."},{"text":"Add the onions, carrots, celery, parsnip (if using), parsley and bay leaf. Reduce heat to low and simmer gently, uncovered, for 1½ to 2 hours. The broth should be clear and golden. Season with salt and pepper to taste."},{"text":"While the broth simmers, make the matzo balls: beat the eggs with oil and soda water until combined. Stir in the matzo meal, salt, white pepper and ginger (if using) until just mixed, the batter will be thick and slightly chunky. Cover and refrigerate for 30 minutes."},{"text":"Bring a large pot of salted water to a boil until it is at a steady rolling boil (use a separate pot so it doesn't interfere with your broth simmering). With cold, wet hands, gently roll the matzo batter into balls about 4 cm in diameter. Place them on a wet plate as you go."},{"text":"Carefully drop the matzo balls into the boiling water one at a time. They will sink, then float to the surface after a few minutes. Once they float, simmer them gently for 30 minutes, do not let them boil hard or they'll become tough."},{"text":"Strain the broth through a fine sieve, discarding the vegetables and bones. Return to a clean pot and gently reheat. Carefully transfer the matzo balls to serving bowls and ladle the golden broth over them. Serve hot."}],"id":"3d5c87df-8271-4906-b495-5a829dc39f55"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;